package au.monster.tracker;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** Native offline Android UI; no WebView and no networking code. */
public final class MainActivity extends Activity {
    private static final int BG=0xff101410,CARD=0xff20271d,GREEN=0xffb6f552,TEXT=0xfff0f5eb,MUTED=0xffa6b29c;
    private static final int CREATE_FILE=41,OPEN_FILE=42;
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private Store store;private Store.Snapshot state;private LinearLayout root,body,nav;private TextView status;
    private int tab=0,historyLimit=100;private boolean busy=false,dead=false;private String message="All data stays on this device.",exportKind="backup";
    private Uri deferredDocument;private int deferredRequest;
    private final List<View> controls=new ArrayList<>();
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);if(saved!=null){tab=saved.getInt("tab",0);exportKind=saved.getString("exportKind","backup");deferredRequest=saved.getInt("deferredRequest",0);String document=saved.getString("deferredDocument");if(document!=null)deferredDocument=Uri.parse(document);}store=new Store(this);buildRoot();job(()->{var pending=store.recoverPending();if(pending!=null){store.acknowledge(pending.id());message="Recovered the last save exactly once.";}return store.snapshot();},s->{state=s;render();});}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("tab",tab);b.putString("exportKind",exportKind);b.putInt("deferredRequest",deferredRequest);if(deferredDocument!=null)b.putString("deferredDocument",deferredDocument.toString());}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable background(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));return v;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private void buildRoot(){root=column();root.setBackgroundColor(BG);root.setPadding(dp(16),0,dp(16),0);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop(),dp(16),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();TextView title=text("Monster Tracker",24,TEXT);title.setTypeface(null,Typeface.BOLD);root.addView(title);status=text(message,13,MUTED);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=column();body.setPadding(0,dp(8),0,dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(64)));}
    private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(TEXT);b.setBackground(background(CARD,14));b.setMinHeight(dp(56));b.setPadding(dp(10),dp(10),dp(10),dp(10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(5));b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)action.run();});b.setEnabled(!busy);controls.add(b);return b;}
    private void addButton(String s,Runnable r){body.addView(button(s,r));}
    private void heading(String s){TextView h=text(s,23,TEXT);h.setTypeface(null,Typeface.BOLD);body.addView(h);}
    private void paragraph(String s){body.addView(text(s,15,MUTED));}
    private EditText field(LinearLayout parent,String label,String initial,int type){parent.addView(text(label,15,TEXT));EditText e=new EditText(this);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(18);e.setInputType(type);e.setText(initial);e.setSingleLine(type!=InputType.TYPE_CLASS_TEXT);e.setPadding(dp(12),dp(12),dp(12),dp(12));e.setBackground(background(CARD,10));e.setMinHeight(dp(54));parent.addView(e,new LinearLayout.LayoutParams(-1,-2));controls.add(e);return e;}
    private EditText amount(String label,long cents){return field(body,label,Ledger.inputMoney(cents),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);}
    private RadioGroup choices(String label,String[] values,String[] names,Consumer<String> change){body.addView(text(label,15,TEXT));RadioGroup g=new RadioGroup(this);g.setOrientation(RadioGroup.HORIZONTAL);for(int i=0;i<values.length;i++){RadioButton r=new RadioButton(this);r.setId(View.generateViewId());r.setTag(values[i]);r.setText(names[i]);r.setTextColor(TEXT);r.setTextSize(16);r.setMinHeight(dp(52));g.addView(r,new RadioGroup.LayoutParams(0,-2,1));controls.add(r);}g.check(g.getChildAt(0).getId());g.setOnCheckedChangeListener((group,id)->{RadioButton r=group.findViewById(id);if(r!=null)change.accept((String)r.getTag());});body.addView(g);return g;}
    private String selected(RadioGroup g){return (String)g.findViewById(g.getCheckedRadioButtonId()).getTag();}
    private void render(){if(dead)return;controls.clear();body.removeAllViews();nav.removeAllViews();status.setText(message+(busy?" · Saving…":""));String[] labels={"Home","Sale","Stock","History","Settings"};for(int i=0;i<labels.length;i++){final int index=i;Button b=button(labels[i],()->{tab=index;render();});b.setTextSize(11);b.setTextColor(tab==i?BG:MUTED);b.setBackground(background(tab==i?GREEN:BG,8));nav.addView(b,new LinearLayout.LayoutParams(0,-1,1));}if(state==null){paragraph("Opening local database…");return;}switch(tab){case 0->dashboard();case 1->sale();case 2->stock();case 3->history();case 4->settings();}}
    private void metric(String label,String value){LinearLayout c=column();c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(background(CARD,16));c.addView(text(label,14,MUTED));TextView v=text(value,28,TEXT);v.setTypeface(null,Typeface.BOLD);c.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));body.addView(c,p);}
    private void dashboard(){var t=state.totals();heading("Your stock, at a glance");LinearLayout hero=column();hero.setPadding(dp(20),dp(16),dp(20),dp(16));hero.setBackground(background(GREEN,22));hero.addView(text("CANS REMAINING",14,BG));TextView count=text(Long.toString(t.stock()),64,BG);count.setTypeface(null,Typeface.BOLD);hero.addView(count);hero.addView(text("100% offline · AUD · Perth time",14,BG));body.addView(hero);addButton("Record a sale",()->{tab=1;render();});metric("Total cans sold",Long.toString(t.sold()));metric("Singles / two-can deals",t.singles()+" / "+t.deals());metric("Missing / damaged / lost",Long.toString(t.missing()));metric("Revenue",Ledger.money(t.revenue()));metric("Cash / card revenue",Ledger.money(t.cash())+" / "+Ledger.money(t.card()));metric("Purchase costs",Ledger.money(t.purchases()));metric("Actual card fees",Ledger.money(t.fees()));metric("Cash result",Ledger.money(t.result()));paragraph("Cash result = all revenue − card fees − all purchase costs. Card records a payment only. Opening dates remain unknown.");}
    private void sale(){heading("Record sale");paragraph(state.totals().stock()+" cans available");final String[] type={"single"};RadioGroup quantity=choices("Quantity",new String[]{"single","deal"},new String[]{"1 can","2-can deal"},s->{});EditText price=amount("Sale total (AUD)",state.prices().single());quantity.setOnCheckedChangeListener((g,id)->{type[0]=selected(quantity);price.setText(Ledger.inputMoney(type[0].equals("single")?state.prices().single():state.prices().deal()));});RadioGroup payment=choices("Payment",new String[]{"cash","card"},new String[]{"Cash","Card"},s->{});EditText fee=amount("Actual card fee (AUD)",0);fee.setEnabled(false);payment.setOnCheckedChangeListener((g,id)->{boolean card=selected(payment).equals("card");fee.setEnabled(card&&!busy);if(!card)fee.setText("0.00");});long[] when={System.currentTimeMillis()};Button date=button(Ledger.displayTime(when[0]),()->pickTime(when,()->{}));date.setOnClickListener(v->{if(!busy)pickTime(when,()->date.setText(Ledger.displayTime(when[0])));});body.addView(text("Sale date & time (Perth)",15,TEXT));body.addView(date);EditText note=field(body,"Optional note","",InputType.TYPE_CLASS_TEXT);Button confirm=button("Confirm sale",()->{try{String kind=selected(quantity),pay=selected(payment);var event=Ledger.event(kind,kind.equals("single")?1:2,pay,Ledger.cents(price.getText().toString()),pay.equals("card")?Ledger.cents(fee.getText().toString()):0,0,note.getText().toString(),when[0],null);save(event,"Sale saved locally.");}catch(Exception e){error(e);}});body.addView(confirm);confirm.setEnabled(state.totals().stock()>=1&&!busy);paragraph("Amounts and actual fees are stored with this sale. Later price changes will not rewrite it.");}
    private void pickTime(long[] when,Runnable changed){ZonedDateTime z=Instant.ofEpochMilli(when[0]).atZone(Ledger.PERTH);new DatePickerDialog(this,(view,year,month,day)->new TimePickerDialog(this,(time,hour,minute)->{try{when[0]=LocalDateTime.of(year,month+1,day,hour,minute).atZone(Ledger.PERTH).toInstant().toEpochMilli();changed.run();}catch(Exception e){error(e);}},z.getHour(),z.getMinute(),true).show(),z.getYear(),z.getMonthValue()-1,z.getDayOfMonth()).show();}
    private void stock(){heading("Stock");metric("Available inventory",Long.toString(state.totals().stock()));paragraph("Original: 24 cans for $50. Four opening missing cans have an unknown date.");TextView h=text("Add purchased stock",20,TEXT);body.addView(h);EditText q=field(body,"Cans purchased","24",InputType.TYPE_CLASS_NUMBER);EditText cost=amount("Total purchase cost (AUD)",5000);EditText note=field(body,"Purchase note","",InputType.TYPE_CLASS_TEXT);addButton("Confirm purchase",()->{try{save(Ledger.event("restock",quantity(q),"none",0,0,Ledger.cents(cost.getText().toString()),note.getText().toString(),System.currentTimeMillis(),null),"Stock purchase saved.");}catch(Exception e){error(e);}});body.addView(text("Missing, damaged or lost",20,TEXT));RadioGroup kind=choices("Reason",new String[]{"missing","damaged","lost"},new String[]{"Missing","Damaged","Lost"},s->{});EditText loss=field(body,"Cans removed","1",InputType.TYPE_CLASS_NUMBER);EditText lossNote=field(body,"Optional details","",InputType.TYPE_CLASS_TEXT);addButton("Confirm stock removal",()->{try{save(Ledger.event(selected(kind),quantity(loss),"none",0,0,0,lossNote.getText().toString(),System.currentTimeMillis(),null),"Stock adjustment saved; no sale revenue.");}catch(Exception e){error(e);}});}
    private long quantity(EditText e){try{long n=Long.parseLong(e.getText().toString().trim());if(n<1||n>10000)throw new NumberFormatException();return n;}catch(NumberFormatException ex){throw new IllegalArgumentException("Quantity must be 1–10,000 cans.");}}
    private void history(){heading("Transaction history");paragraph("Tap a record for details or traceable undo. No transaction can be deleted.");Set<String> corrected=new HashSet<>();for(var e:state.events())if(e.type().equals("undo"))corrected.add(e.target());int shown=0;for(int i=state.events().size()-1;i>=0&&shown<historyLimit;i--,shown++){var e=state.events().get(i);String label=e.type().equals("undo")?"UNDO / CORRECTION":e.type().toUpperCase(Locale.ENGLISH)+" · "+e.quantity()+" cans";if(e.revenue()>0)label+=" · "+Ledger.money(e.revenue());if(corrected.contains(e.id()))label+=" · corrected";String finalLabel=label;addButton(finalLabel+"\n"+Ledger.displayTime(e.timestamp()),()->details(e,corrected.contains(e.id())));}if(state.events().size()>historyLimit)addButton("Show 100 more",()->{historyLimit+=100;render();});}
    private void details(Ledger.Event e,boolean corrected){String detail="ID: "+e.id()+"\nEvent date: "+Ledger.displayTime(e.timestamp())+"\nUTC: "+(e.timestamp()==null?"Unknown":Ledger.iso(e.timestamp()))+"\nRecorded on device: "+Ledger.displayTime(e.recordedAt())+"\nQuantity: "+e.quantity()+"\nPayment: "+e.payment()+"\nRevenue / stored sale price: "+Ledger.money(e.revenue())+"\nActual fee: "+Ledger.money(e.fee())+"\nPurchase cost: "+Ledger.money(e.cost())+"\nNote: "+e.note()+(e.target()==null?"":"\nCorrects: "+e.target());AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle(e.type()+ (corrected?" — corrected":"")).setMessage(detail).setPositiveButton("Close",null);if(!corrected&&!e.type().equals("undo"))d.setNegativeButton("Undo…",(a,b)->undo(e));d.show();}
    private void undo(Ledger.Event e){EditText reason=new EditText(this);reason.setHint("Reason for correction");reason.setText("Correction of "+e.type());new AlertDialog.Builder(this).setTitle("Undo this transaction?").setMessage("The original remains in history. A new undo record will reverse its effects. To edit a sale, undo it and enter the corrected sale.").setView(reason).setNegativeButton("Cancel",null).setPositiveButton("Confirm undo",(d,w)->{try{save(Ledger.event("undo",0,"none",0,0,0,reason.getText().toString(),System.currentTimeMillis(),e.id()),"Undo saved. Original history retained.");}catch(Exception ex){error(ex);}}).show();}
    private void settings(){heading("Settings & backups");EditText single=amount("Default single price (AUD)",state.prices().single());EditText deal=amount("Default two-can deal (AUD)",state.prices().deal());addButton("Save future sale prices",()->{try{var p=new Ledger.Prices(Ledger.cents(single.getText().toString()),Ledger.cents(deal.getText().toString()));job(()->{store.setPrices(p);return store.snapshot();},s->{state=s;message="Future prices saved. Historical amounts unchanged.";render();});}catch(Exception e){error(e);}});addButton("Export full JSON backup",()->createFile("backup"));addButton("Import / restore JSON backup",this::openBackup);addButton("Export transaction history CSV",()->createFile("csv"));paragraph("Choose an on-device folder such as Downloads. You can copy JSON backups to a USB drive or another phone without internet. CSV is for viewing history, not restoring.");paragraph("Uninstalling the app, clearing app data, losing or resetting your phone can erase the local database. Export regularly and keep a copy away from this phone. Android cloud backup is disabled. Backups are not encrypted; keep them private.");paragraph("Restore merges validated transactions without overwriting or deleting existing history. Matching IDs are skipped; conflicting IDs and invalid files are rejected. Price settings from the backup require confirmation.");}
    private void save(Ledger.Event e,String success){job(()->{store.stage(e);store.recoverPending();return store.snapshot();},s->{state=s;message=success;tab=0;render();io.execute(()->{try{store.acknowledge(e.id());}catch(Exception ignored){/* next launch safely recovers the same ID */}});});}
    private <T> void job(Callable<T> action,Consumer<T> done){if(busy)return;busy=true;for(View v:controls)v.setEnabled(false);status.setText("Working locally…");io.execute(()->{try{T result=action.call();runOnUiThread(()->{if(dead)return;busy=false;done.accept(result);resumeDocument();});}catch(Exception e){runOnUiThread(()->{if(dead)return;busy=false;message="Not saved: "+safeMessage(e);render();error(e);});}});}
    private String safeMessage(Exception e){return e.getMessage()==null?"Operation failed. No records were deleted.":e.getMessage();}
    private void error(Exception e){message=safeMessage(e);if(status!=null)status.setText(message);new AlertDialog.Builder(this).setTitle("Could not complete").setMessage(message).setPositiveButton("OK",null).show();}
    private void createFile(String kind){exportKind=kind;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(kind.equals("csv")?"text/csv":"application/json");intent.putExtra(Intent.EXTRA_TITLE,"monster-"+LocalDate.now(Ledger.PERTH)+ (kind.equals("csv")?"-history.csv":"-backup.json"));try{startActivityForResult(intent,CREATE_FILE);}catch(ActivityNotFoundException e){error(new IllegalStateException("No document picker available on this device."));}}
    private void openBackup(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");try{startActivityForResult(intent,OPEN_FILE);}catch(ActivityNotFoundException e){error(new IllegalStateException("No document picker available on this device."));}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(busy){deferredDocument=uri;deferredRequest=request;return;}if(request==CREATE_FILE){String kind=exportKind;job(()->{var s=store.snapshot();String content=kind.equals("csv")?Backup.csv(s.events()):Backup.encode(new Backup.Data(s.events(),s.prices()));try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Could not open destination.");out.write(content.getBytes(StandardCharsets.UTF_8));out.flush();}return uri;},u->{message="Export complete. Keep a copy outside this phone.";render();});}else if(request==OPEN_FILE)job(()->{String content=readBackup(uri);var incoming=Backup.decode(content);var current=store.snapshot();var merged=Ledger.merge(current.events(),incoming.events());return new ImportPreview(incoming,merged.size()-current.events().size(),current.events().size());},this::confirmRestore);}
    private void resumeDocument(){if(deferredDocument!=null&&!busy){Uri uri=deferredDocument;int request=deferredRequest;deferredDocument=null;deferredRequest=0;onActivityResult(request,RESULT_OK,new Intent().setData(uri));}}
    private record ImportPreview(Backup.Data data,int added,int current){}
    private void confirmRestore(ImportPreview p){render();new AlertDialog.Builder(this).setTitle("Restore validated backup?").setMessage("Existing records: "+p.current+"\nNew records to add: "+p.added+"\nMatching IDs will be skipped. Nothing will be deleted or overwritten.\n\nFuture prices will become "+Ledger.money(p.data.prices().single())+" / "+Ledger.money(p.data.prices().deal())+". Export your current JSON backup first if needed.").setNegativeButton("Cancel",(d,w)->{message="Restore cancelled. No changes.";status.setText(message);}).setPositiveButton("Merge & restore",(d,w)->job(()->{int n=store.importBackup(p.data);return new RestoreResult(n,store.snapshot());},r->{state=r.snapshot;message="Restored "+r.count+" new records. Existing history retained.";render();})).show();}
    private record RestoreResult(int count,Store.Snapshot snapshot){}
    private String readBackup(Uri uri)throws IOException {try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Could not open backup.");byte[] b=new byte[8192];int total=0,n;while((n=in.read(b))!=-1){total+=n;if(total>Backup.MAX_BYTES)throw new IOException("Backup exceeds 64 MB.");out.write(b,0,n);}try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(out.toByteArray())).toString();}catch(CharacterCodingException ex){throw new IOException("Backup is not valid UTF-8.");}}}
}
